10	/**
11	 * Derives an owner's {@code memberId}, the {@code <REGION><FY><HASH8><CHK>} identity every
12	 * other owner-id-derived value is built from.
13	 *
14	 * <p>{@code REGION} is the region code derived from the owner's postcode
15	 * ({@link Localities#forPostcode(String)}), or {@code UNKNOWN} when the postcode is
16	 * absent or in no known range. {@code FY} is the two-digit fiscal year of the
17	 * (business-day-adjusted) {@code registrationDate} (see {@link FiscalYears}), or
18	 * {@code 00} when unset. {@code HASH8} is the first 8 upper-case hex characters of the
19	 * SHA-256 digest of the normalized telephone ({@link Telephones#toE164(String)})
20	 * concatenated with the last name. {@code CHK} is a single Luhn check digit
21	 * ({@link CheckDigits#luhn(String)}) computed over the digits of {@code <REGION><FY><HASH8>}.
22	 * There are no sequence numbers: the base identity is a pure function of the owner's
23	 * own fields.
24	 *
25	 * <p>Centralising the derivation here keeps {@link AssignMemberId} (which assigns the
26	 * memberId) and the {@code locality} mapping (which derives the region) in exact
27	 * agreement.
28	 */
29	public final class MemberIds {
30	
31	    private MemberIds() {
32	    }
33	
34	    /** The base {@code <REGION><FY><HASH8><CHK>} memberId for the given owner. */
35	    public static String forOwner(Owner owner) {
36	        String region = region(owner.getPostcode());
37	        String fy = owner.getRegistrationDate() == null ? "00"
38	                : String.format("%02d", FiscalYears.yearSegment(owner.getRegistrationDate()));
39	        String base = region + fy + hash8(owner);
40	        return base + CheckDigits.luhn(base);
41	    }
42	
43	    /**
44	     * The owner's locality: the region derived from its postcode — the same {@code REGION}
45	     * segment that opens its memberId.
46	     */
47	    public static String localityOf(Owner owner) {
48	        return region(owner.getPostcode());
49	    }
50	
51	    /**
52	     * The owner's IANA timezone, derived from its {@link #localityOf(Owner) locality}
53	     * via the fixed region-to-timezone table, or {@code null} when the region is unknown.
54	     */
55	    public static String timezoneOf(Owner owner) {
56	        return Localities.timezoneForRegion(localityOf(owner));
57	    }
58	
59	    /** The region code derived from a postcode, or {@code UNKNOWN} when unresolved. */
60	    public static String region(String postcode) {
61	        String region = Localities.forPostcode(postcode);
62	        return region != null ? region : "UNKNOWN";
63	    }
64	
65	    /** First 8 upper-case hex chars of SHA-256 over (normalizedTelephone + lastName). */
66	    private static String hash8(Owner owner) {
67	        String telephone = Telephones.toE164(owner.getTelephone());
68	        String lastName = owner.getLastName();
69	        String basis = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
70	        return Digests.sha256Hex(basis).substring(0, 8).toUpperCase(Locale.ROOT);
71	    }
72	}
