3	/**
4	 * Computes a single Luhn check digit (0-9) over the digits contained in a value.
5	 * Non-digit characters are ignored; the rightmost digit is doubled and doubling
6	 * alternates leftward. Used to derive the {@code CHK} segment of an owner's memberId.
7	 */
8	public final class CheckDigits {
9	
10	    private CheckDigits() {
11	    }
12	
13	    /** The Luhn check digit (0-9) over the digits contained in {@code value}. */
14	    public static int luhn(String value) {
15	        if (value == null) {
16	            return 0;
17	        }
18	        int sum = 0;
19	        boolean dbl = true;
20	        for (int i = value.length() - 1; i >= 0; i--) {
21	            char c = value.charAt(i);
22	            if (c < '0' || c > '9') {
23	                continue;
24	            }
25	            int d = c - '0';
26	            if (dbl) {
27	                d *= 2;
28	                if (d > 9) {
29	                    d -= 9;
30	                }
31	            }
32	            sum += d;
33	            dbl = !dbl;
34	        }
35	        return (10 - (sum % 10)) % 10;
36	    }
37	}
