1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	import java.util.regex.Pattern;
5	
6	import org.springframework.samples.petclinic.mapper.Localities;
7	
8	/**
9	 * Validates an owner's optional postcode against its city's region.
10	 *
11	 * <p>A postcode, when supplied, must be exactly 4 digits and fall within the
12	 * inclusive range fixed for the region derived from the owner's city
13	 * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region
14	 * (locality {@code UNKNOWN}) accepts any 4-digit postcode.
15	 */
16	public final class Postcodes {
17	
18	    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");
19	
20	    /** Region -> inclusive {low, high} 4-digit postcode range. */
21	    private static final Map<String, int[]> REGION_RANGE = Map.of(
22	        "NSW", new int[] {2000, 2099},
23	        "VIC", new int[] {3000, 3099},
24	        "QLD", new int[] {4000, 4099});
25	
26	    private Postcodes() {
27	    }
28	
29	    /**
30	     * Whether the postcode is acceptable for the given city. A blank/absent postcode
31	     * is acceptable (validated only when present). When present it must be 4 digits and,
32	     * for a city with a known region, within that region's range.
33	     */
34	    public static boolean isValid(String postcode, String city) {
35	        if (postcode == null || postcode.isBlank()) {
36	            return true;
37	        }
38	        if (!FOUR_DIGITS.matcher(postcode).matches()) {
39	            return false;
40	        }
41	        int[] range = REGION_RANGE.get(Localities.forCity(city));
42	        if (range == null) {
43	            return true;
44	        }
45	        int value = Integer.parseInt(postcode);
46	        return value >= range[0] && value <= range[1];
47	    }
48	}
