1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * American Soundex encoding of a name — a phonetic code (a leading letter followed by three
5	 * digits) that folds names sounding alike onto the same value. It is the last-name component
6	 * of an owner's {@link IdentityKeys identity key} and the phonetic axis of the soft-match in
7	 * {@link AssignPossibleDuplicate}, so centralising it here keeps both in exact agreement.
8	 *
9	 * <p>Non-letters are ignored; a null or letterless value yields {@code "0000"}. Consonants
10	 * with the same code are collapsed when adjacent or separated only by {@code H}/{@code W},
11	 * but coded twice when separated by a vowel — the standard algorithm.
12	 */
13	public final class Soundex {
14	
15	    private Soundex() {
16	    }
17	
18	    /** The Soundex code (a letter followed by three digits) for {@code name}. */
19	    public static String encode(String name) {
20	        if (name == null) {
21	            return "0000";
22	        }
23	        StringBuilder letters = new StringBuilder();
24	        for (int i = 0; i < name.length(); i++) {
25	            char c = name.charAt(i);
26	            if (Character.isLetter(c)) {
27	                letters.append(Character.toUpperCase(c));
28	            }
29	        }
30	        if (letters.length() == 0) {
31	            return "0000";
32	        }
33	        StringBuilder code = new StringBuilder();
34	        code.append(letters.charAt(0));
35	        char previous = codeOf(letters.charAt(0));
36	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
37	            char c = letters.charAt(i);
38	            if (c == 'H' || c == 'W') {
39	                // H and W do not separate: keep the previous code so a repeat stays collapsed.
40	                continue;
41	            }
42	            char digit = codeOf(c);
43	            if (digit != '0' && digit != previous) {
44	                code.append(digit);
45	            }
46	            // A vowel resets the previous code, so a later same-code consonant IS coded twice.
47	            previous = digit;
48	        }
49	        while (code.length() < 4) {
50	            code.append('0');
51	        }
52	        return code.toString();
53	    }
54	
55	    /** The Soundex digit for a letter; {@code '0'} for vowels (A E I O U Y) and H/W. */
56	    private static char codeOf(char c) {
57	        switch (c) {
58	            case 'B': case 'F': case 'P': case 'V':
59	                return '1';
60	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
61	                return '2';
62	            case 'D': case 'T':
63	                return '3';
64	            case 'L':
65	                return '4';
66	            case 'M': case 'N':
67	                return '5';
68	            case 'R':
69	                return '6';
70	            default:
71	                return '0';
72	        }
73	    }
74	}
