8	/**
9	 * Assigns the new owner's {@code membershipLevelCap}: a ceiling of one above the current
10	 * maximum membership level among their existing household members (owners already sharing
11	 * this owner's {@code householdId}). Runs after {@link AssignHousehold} sets the id but
12	 * before the owner is saved, so only pre-existing members are considered. When the owner
13	 * has no household ({@code null} id) or no existing household member, no cap applies and
14	 * the field is left {@code null}. {@link MembershipLevels#forOwner(Owner)} enforces the cap.
15	 */
16	public class AssignMembershipLevelCap {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String householdId = owner.getHouseholdId();
20	        if (householdId == null) {
21	            return;
22	        }
23	        int maxLevel = -1;
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (householdId.equals(existing.getHouseholdId())) {
26	                maxLevel = Math.max(maxLevel, MembershipLevels.forOwner(existing));
27	            }
28	        }
29	        if (maxLevel >= 0) {
30	            owner.setMembershipLevelCap(maxLevel + 1);
31	        }
32	    }
33	}
