9	 * Assigns the owner's {@code possibleDuplicate} / {@code possibleDuplicateOf}: a soft-match
10	 * flag for a new owner that is not a hard duplicate but still looks like one.
11	 *
12	 * <p>A create is only rejected (409) when the new owner exactly matches an existing owner's
13	 * {@link IdentityKeys identity key} (see {@link RequireUniqueIdentity}), so by the time this
14	 * step runs no existing owner shares that key. Here we flag the weaker signal: an existing
15	 * owner whose {@code identityKey} differs but whose {@code soundex(lastName)} and
16	 * {@code postcode} both match — i.e. the same household by name and postcode, distinguished
17	 * only by telephone or email. A <em>declared</em> household member ({@code sharesHousehold})
18	 * is intentionally never flagged — a declared member is not a suspected duplicate. Otherwise,
19	 * when a match is found the owner is still created, but with {@code possibleDuplicate} true
20	 * and {@code possibleDuplicateOf} set to the (lowest) matching owner id; when none is found
21	 * {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left unset.
22	 *
23	 * <p>Runs after {@link BuildOwner} (so the owner's fields are set) and before
24	 * {@link SaveOwner} (so the new owner is not compared against itself).
25	 */
26	public class AssignPossibleDuplicate {
27	
28	    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
29	            OwnerRepository ownerRepository) {
30	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
31	            // A declared household member is not a suspected duplicate.
32	            owner.setPossibleDuplicate(false);
33	            owner.setPossibleDuplicateOf(null);
34	            return;
35	        }
36	        String lastName = owner.getLastName();
37	        String postcode = owner.getPostcode();
38	        String soundex = Soundex.encode(lastName);
39	        String identityKey = IdentityKeys.forOwner(owner);
40	        Integer matchId = null;
41	        if (lastName != null && postcode != null && !postcode.isBlank()) {
42	            for (Owner existing : ownerRepository.findAll()) {
43	                if (Boolean.TRUE.equals(existing.getDeleted())) {
44	                    continue; // a soft-deleted owner is not a possible duplicate
45	                }
46	                if (identityKey.equals(IdentityKeys.forOwner(existing))) {
47	                    continue; // an exact identity match is a hard duplicate, not a soft one
48	                }
49	                if (soundex.equals(Soundex.encode(existing.getLastName()))
50	                        && postcode.equals(existing.getPostcode())
51	                        && (matchId == null || existing.getId() < matchId)) {
52	                    matchId = existing.getId();
53	                }
54	            }
55	        }
56	        owner.setPossibleDuplicate(matchId != null);
57	        owner.setPossibleDuplicateOf(matchId);
58	    }
59	}
